echo '<html><head><meta charset="UTF-8"><title>RESULTS・POINT インポート</title></head><body>';
echo '<h1>実績 RESULTS・POINT 一括インポート</h1><pre>';

$success = 0; $skip = 0; $error = 0;

foreach ( $data as $slug => $values ) {
    $posts = get_posts( [ 'post_type' => 'works', 'name' => $slug, 'post_status' => 'publish', 'numberposts' => 1 ] );
    if ( empty( $posts ) ) {
        echo "✗ [{$slug}] 投稿が見つかりません\n";
        $error++;
        continue;
    }
    $post_id = $posts[0]->ID;
    foreach ( $fields as $key ) {
        $meta_key = '_works_' . $key;
        $val = isset( $values[$key] ) ? $values[$key] : '';
        update_post_meta( $post_id, $meta_key, $val );
    }
    echo "✓ [{$slug}] 設定完了\n";
    $success++;
}

echo "\n========================================\n";
echo "完了: 成功 {$success} / エラー {$error}\n";
